      background: linear-gradient(180deg, #171b2e 0%, #13172a 100%);
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 16px 18px;
      margin-bottom: 14px;
      box-shadow: 0 8px 24px rgba(0,0,0,0.2);
    }
    .kpi-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(180px, 1fr));
      gap: 10px;
    }
    .kpi {
      background: var(--panel-2);
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 12px;
    }
    .kpi .v { font-size: 28px; font-weight: 700; color: var(--accent-2); margin-bottom: 4px; }
    .kpi .k { font-size: 13px; color: var(--muted); }
    .grid-2 { display: grid; grid-template-columns: 1.1fr 1fr; gap: 14px; }
    .grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
    .panel h2 { margin: 0 0 10px; font-size: 20px; }
    .panel h3 { margin: 0 0 8px; font-size: 17px; color: #d8e2ff; }
    .meta { color: var(--muted); font-size: 13px; }
    .table-wrap { overflow-x: auto; }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 13px;
      background: rgba(255,255,255,0.01);
      border: 1px solid var(--border);
    }
    th, td { border-bottom: 1px solid var(--border); padding: 8px 9px; text-align: left; }
    th { background: #20284a; color: #eef2ff; font-weight: 650; }
    tr:hover td { background: rgba(138, 180, 255, 0.06); }
    ul.tight { margin: 8px 0 0 16px; padding: 0; }
    ul.tight li { margin-bottom: 6px; }
    .note { color: var(--muted); font-size: 13px; margin-top: 8px; }
    .foot { font-size: 12px; color: #9da8d3; margin-top: 16px; }
